// Replaces all records of the Algolia docs index with the index file generated by Hugo.
// Settings, rules and synonyms of the existing index are kept.
import { readFile } from 'node:fs/promises';
import { algoliasearch } from 'algoliasearch';

const env = {
  ALGOLIA_APP_ID: process.env.ALGOLIA_APP_ID,
  ALGOLIA_ADMIN_KEY: process.env.ALGOLIA_ADMIN_KEY,
  ALGOLIA_INDEX_NAME: process.env.ALGOLIA_INDEX_NAME,
  ALGOLIA_INDEX_FILE: process.env.ALGOLIA_INDEX_FILE,
};

for (const [name, value] of Object.entries(env)) {
  if (!value) {
    throw new Error(`Please provide ${name}`);
  }
}

const objects = JSON.parse(await readFile(env.ALGOLIA_INDEX_FILE, 'utf8'));
const client = algoliasearch(env.ALGOLIA_APP_ID, env.ALGOLIA_ADMIN_KEY);

await client.replaceAllObjects({ indexName: env.ALGOLIA_INDEX_NAME, objects });

console.log(`Uploaded ${objects.length} records to ${env.ALGOLIA_INDEX_NAME}`);
